// ============================================================
// PREPARAR ENTRADA — v2 (intervenção humana no contexto)
//
// NOVO na v2:
//   - O histórico preserva o campo "autor" de cada mensagem:
//     'cliente', 'agente_ia' (Carol) ou 'equipe_humana' (Samuel
//     interveio manualmente). Se o payload vier de uma versão
//     antiga do Omnichannel (sem autor), o autor é deduzido por
//     direccao + origem.
//   - Se houve intervenção humana, entra uma nota em
//     dados.intervencao_humana mandando o orquestrador ler as
//     mensagens da equipe e tratá-las como palavra final (a regra
//     completa está no system message dos orquestradores).
// O resto é idêntico à versão anterior.
// ============================================================
let p = $json.payload ?? $json;
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch (e) { p = {}; }
}
if (p && typeof p.payload === 'object') p = p.payload; // caso venha aninhado

const contexto = p.contexto || {};

const historicoBruto = Array.isArray(p.historico)
  ? p.historico
  : (p.historico?.mensagens || []);

const historico = historicoBruto
  .slice(-30)
  .map(m => {
    const direccao = m.direccao || m.direcao || '';
    const origem = String(m.origem || '');
    const autor = m.autor ||
      (direccao === 'recebida' ? 'cliente' : (origem === 'humano' ? 'equipe_humana' : 'agente_ia'));
    return {
      autor,
      direccao,
      tipo: m.tipo || 'texto',
      conteudo: m.conteudo || ''
    };
  })
  .filter(m => m.conteudo);

// ---------------------------------------------------------------
// INTERVENÇÃO HUMANA (NOVO v2)
// Se a equipe (Samuel) mandou mensagem manualmente, o orquestrador
// precisa saber — principalmente quando a equipe falou DEPOIS da
// última resposta da IA (a Carol está retomando a conversa agora).
// ---------------------------------------------------------------
const intervencaoPayload = p.intervencao_humana || {};
const msgsEquipe = historico.filter(m => m.autor === 'equipe_humana');
const houveIntervencao = intervencaoPayload.houve === true || msgsEquipe.length > 0;
let notaIntervencao = '';
if (houveIntervencao) {
  const maisRecente = intervencaoPayload.mais_recente_que_ia === true;
  notaIntervencao =
    'ATENÇÃO: um humano da equipe (autor "equipe_humana" no histórico — normalmente o Samuel) ' +
