// idioma continuava errado e o Redator se apoiava nele. Regra nova:
//  - a ÚLTIMA mensagem do cliente tem sinal claro de idioma → esse idioma manda;
//  - mensagem curta/ambígua ("ok", "👍", número, horário) → mantém o do contexto.
function medirIdioma(texto) {
  const t = ' ' + normalizarTexto(texto) + ' ';
  if (t.trim().length < 4) return '';
  const marcas = {
    en: ['the','you','your','are','is','what','where','when','how','much','do','does','can','could','would','like','want','need','have','and','for','with','please','thanks','thank','hi','hello','hey','guys','located','open','price','cost','appointment','book','schedule','it','my','me','about','time','today','tomorrow','week','available','yes','this','that'],
    es: ['hola','donde','cuando','cuanto','como','que','quiero','quisiera','necesito','ustedes','usted','gracias','por','favor','precio','cuesta','cita','agendar','estan','esta','tienen','tiene','hacer','puedo','pueden','una','los','las','mi','para','con','hoy','manana','semana','abierto','buenos','buenas','dias','tardes','noches','si','ubicados','y'],
    pt: ['ola','oi','onde','quando','quanto','como','que','quero','queria','gostaria','preciso','voces','vcs','obrigado','obrigada','por','favor','preco','custa','valor','agendar','marcar','avaliacao','ficam','fica','estao','esta','tem','fazer','posso','podem','uma','os','as','meu','minha','para','pra','com','hoje','amanha','semana','aberto','bom','boa','dia','dias','tarde','tardes','noite','noites','sim','nao','e','ou','vim','anuncio','pele','apos','depois','antes','sabado','sabados','domingo','segunda','terca','quarta','quinta','sexta','feira','tambem','ja','entao','pode','consigo','ate','horario','horarios','melhor','manha','so','mais','tudo','voce']
  };
  const palavras = t.trim().split(' ');
  const pontos = { en: 0, es: 0, pt: 0 };
  for (const p of palavras) {
    for (const lang of ['en', 'es', 'pt']) {
      if (marcas[lang].includes(p)) pontos[lang]++;
    }
  }
  // caracteres exclusivos do espanhol ganham peso
  if (/[¿¡ñ]/.test(String(texto || '').toLowerCase())) pontos.es += 2;
  // ç, ã e õ são fortes indícios de português
  if (/[çãõ]/.test(String(texto || '').toLowerCase())) pontos.pt += 2;
  const ordem = ['en', 'es', 'pt'].sort((a, b) => pontos[b] - pontos[a]);
  const melhor = ordem[0];
  const segundo = ordem[1];
  return { lang: melhor, pontos: pontos[melhor], vantagem: pontos[melhor] - pontos[segundo] };
}
// sinal claro para ESTABELECER idioma: pelo menos 2 pontos E vantagem sobre o 2º
function detectarIdioma(texto) {
  const curto = normalizarTexto(texto);
  const saudacoesUnivocas = { oi: 'pt', ola: 'pt', hello: 'en', hi: 'en', hola: 'es' };
  if (saudacoesUnivocas[curto]) return saudacoesUnivocas[curto];
  const s = medirIdioma(texto);
  if (s && s.pontos >= 2 && s.vantagem >= 1) return s.lang;
  return '';
}
// sinal FORTE para TROCAR um idioma já estabelecido: 3+ pontos E vantagem 2+
function detectarIdiomaForte(texto) {
  const s = medirIdioma(texto);
  if (s && s.pontos >= 3 && s.vantagem >= 2) return s.lang;
  return '';
}
// pedido EXPLÍCITO de idioma pelo cliente — manda acima de qualquer placar
function pedidoExplicitoDeIdioma(texto) {
  const t = normalizarTexto(texto);
  if (/\b((in|speak)\s+english|(em|en)\s+(ingles|english)|english\s*,?\s*please)\b/.test(t)) return 'en';
  if (/\b((en|em)\s+(espanol|espanhol)|(in|speak)\s+spanish|hablas?\s+espanol|espanol\s*,?\s*por\s*favor)\b/.test(t)) return 'es';
