function parseJsonSeguro(raw) {
  if (raw && typeof raw === 'object') return raw;
  const texto = String(raw || '')
    .replace(/`{3}json/gi, '')
    .replace(/`{3}/g, '')
    .trim();
  try { return JSON.parse(texto); } catch (e) {}
  // 2ª tentativa: remover caracteres de controlo
  // (quebras de linha literais dentro de strings — erro comum de LLM)
  const limpo = texto.replace(/[\u0000-\u001F]+/g, ' ');
  try { return JSON.parse(limpo); } catch (e) {}
  const match = limpo.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch (e) {}
  }
  return {};
}
