}
function extrairPrecosPermitidos(obj, acc = new Set()) {
  if (obj === null || obj === undefined) return acc;
  if (typeof obj === 'number') {
    acc.add(normalizarNumero(obj));
    return acc;
  }
  if (typeof obj === 'string') {
    const texto = obj.trim();
    const matchesEuro = texto.match(/\d+(?:[.,]\d+)?(?=\s*[€$])|(?<=[€$]\s?)\d+(?:[.,]\d+)?/g) || [];
    matchesEuro.forEach(n => acc.add(normalizarNumero(n)));
    return acc;
  }
  if (Array.isArray(obj)) {
    for (const item of obj) extrairPrecosPermitidos(item, acc);
    return acc;
  }
  if (typeof obj === 'object') {
    for (const [chave, valor] of Object.entries(obj)) {
      if (
        ['preco', 'preco_minimo', 'valor', 'preco_base'].includes(chave) &&
        (typeof valor === 'number' || typeof valor === 'string')
      ) {
        if (String(valor).trim() !== '') acc.add(normalizarNumero(valor));
      }
      if (
        ['precos_por_categoria', 'precos', 'valores'].includes(chave) &&
        valor && typeof valor === 'object'
      ) {
        for (const v of Object.values(valor)) {
          if (typeof v === 'number' || typeof v === 'string') {
            if (String(v).trim() !== '') acc.add(normalizarNumero(v));
          }
        }
      }
      extrairPrecosPermitidos(valor, acc);
    }
  }
  return acc;
}
