    h = Number(h);
    const suf = h >= 12 ? 'PM' : 'AM';
    const h12 = h % 12 === 0 ? 12 : h % 12;
    return `${h12}:${mn} ${suf}`;
  });
  // formato brasileiro 10h / 19h30 / 20H
  msg = msg.replace(/\b([01]?\d|2[0-3])[hH]([0-5]\d)?\b/g, (m, h, mn) => {
    h = Number(h);
    const suf = h >= 12 ? 'PM' : 'AM';
    const h12 = h % 12 === 0 ? 12 : h % 12;
    return `${h12}:${mn || '00'} ${suf}`;
  });
