// remove travessões (estilo ChatGPT) e troca por pontuação natural
function semTravessao(msg) {
  return msg
    .replace(/\s*[—–―]\s*/g, ', ')
    .replace(/\s*--\s*/g, ', ')
    .replace(/,\s*,/g, ', ')
