  for (const f of frases) {
    const nPalavras = textoNormalizado(f).split(' ').filter(Boolean).length;
    if (nPalavras >= 4 && comparaveis.some(e => saoParecidas(e, f))) {
      removeu = true;
      continue;
    }
    mantidas.push(f);
    if (nPalavras >= 4) comparaveis.push(f);
