      fraseNeutraHora = 'Vou verificar os horários disponíveis na agenda e já te retorno, tudo bem?';
    }
    mensagens = [fraseNeutraHora];
    handoff = {
      necessario: true,
      motivo: ('guardrail: resposta citava horário que não existe no briefing nem no histórico' +
        (handoff.necessario && handoff.motivo ? ' + ' + handoff.motivo : '')),
      prioridade: 'alta',
      resumo_para_equipa:
        'O Redator inventou horário(s) que a agenda nunca devolveu e a resposta inteira foi bloqueada. ' +
        'Frases bloqueadas: ' + JSON.stringify(horariosCortados) +
        ' | Horários permitidos neste turno: ' + JSON.stringify(Array.from(horasPermitidas)) +
        ' | O cliente recebeu "vou verificar e já retorno" — RESPONDER com os horários reais da agenda.' +
        (handoff.necessario && handoff.resumo_para_equipa ? ' || Handoff anterior: ' + handoff.resumo_para_equipa : ''),
      mensagem_para_cliente: handoff.mensagem_para_cliente || ''
    };
    erro = erro || 'horario_inventado_bloqueado';
  } else {
    // sobrou resposta útil — entrega o resto e só avisa a equipa, sem pausar o fluxo
    if (!handoff.necessario) {
      handoff = {
        necessario: true,
        motivo: 'guardrail: parte da resposta citava horário inexistente (frase descartada)',
        prioridade: 'normal',
        resumo_para_equipa:
          'Frase(s) com horário inventado descartada(s): ' + JSON.stringify(horariosCortados) +
          ' | Horários permitidos neste turno: ' + JSON.stringify(Array.from(horasPermitidas)),
        mensagem_para_cliente: ''
      };
    }
    erro = erro || 'horario_inventado_parcial';
  }
}
// ---- TRAVA DE DUPLICAÇÃO NO MESMO TURNO ----
// 1) dentro de cada balão: frases quase iguais repetidas → só a primeira fica
mensagens = mensagens.map(semFrasesRepetidas);
// 2) entre balões: se dois balões dizem (quase) a mesma coisa, só o primeiro sobrevive
const semDuplicadas = [];
for (const msg of mensagens) {
  if (!semDuplicadas.some(existente => saoParecidas(existente, msg))) {
    semDuplicadas.push(msg);
  }
}
mensagens = semDuplicadas;
// ---- TRAVA DE DOMINGO OFERECIDO ----
// A clínica não abre ao domingo, mas o orquestrador já ofereceu
// "sábado ou domingo?" mesmo com a regra no prompt. Corte determinístico:
// qualquer OFERTA de domingo como opção vira só sábado, nos 3 idiomas.
// Dizer "domingo não há atendimento" continua permitido — só a oferta cai.
function semDomingoOferecido(msg) {
  return String(msg || '')
    .replace(/\bs[áa]bado\s+(?:ou|o|or)\s+(?:no\s+|el\s+)?domingo\b/gi, 'sábado')
    .replace(/\bdomingo\s+(?:ou|o)\s+(?:no\s+|el\s+)?s[áa]bado\b/gi, 'sábado')
    .replace(/\bsaturday\s+or\s+sunday\b/gi, 'Saturday')
    .replace(/\bsunday\s+or\s+saturday\b/gi, 'Saturday');
}
// ---- TRAVA DE EMOJIS ----
// Política: o agente NUNCA envia emoji, em nenhuma mensagem.
// Remove emojis, bandeiras, tons de pele, ZWJ e keycaps, e limpa
// os espaços/linhas vazias que sobram (ex.: linhas do template que
// começavam com emoji ficam alinhadas à esquerda).
function semEmojis(msg) {
  return String(msg || '')
    .replace(/[\u{1F1E6}-\u{1F1FF}]{2}/gu, '')
    .replace(/\p{Extended_Pictographic}(?:\u{FE0F}|\u{200D}\p{Extended_Pictographic})*/gu, '')
    .replace(/[\u{FE0F}\u{200D}\u{20E3}\u{1F3FB}-\u{1F3FF}]/gu, '')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/^[ \t]+/gm, '')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}
// ---- TRAVA DE ESTILO ----
// sem travessões, sem pedir "WhatsApp", horários sempre AM/PM
mensagens = mensagens
  .map(msg => paraAmPm(semWhatsapp(semTravessao(semDomingoOferecido(semEmojis(msg))))))
  .filter(Boolean);
// dedupe: se o Redator repetiu o texto do template, descarta a cópia
if (mensagemTemplate) {
  const chaveTpl = mensagemTemplate.replace(/\s+/g, ' ').trim().toLowerCase();
  mensagens = mensagens.filter(m => {
    const chaveMsg = m.replace(/\s+/g, ' ').trim().toLowerCase();
    if (chaveMsg === chaveTpl || chaveMsg.includes(chaveTpl) || chaveTpl.includes(chaveMsg)) return false;
    // reforço: paráfrase quase igual ao template também cai (similaridade ≥ 0.7)
    if (saoParecidas(m, mensagemTemplate)) return false;
    return true;
  });
}
// ---- TRAVA DE FOTO DO CLIENTE ----
// briefing.fotos serve para fotos DA CLÍNICA (hospedadas em servidor próprio).
// Fotos que o CLIENTE enviou chegam re-hospedadas na CDN de mensagens da Meta
// (lookaside.fbsbx.com / ig_messaging_cdn) e o orquestrador às vezes cataloga
// essas URLs em "fotos" — se passarem, o agente devolve ao cliente a foto que
// ele próprio mandou, e o eco desse envio ainda dispara falsa intervenção
// humana. Regra: URL da CDN de mensagens da Meta, URL presente no histórico
// da conversa, ou sem URL → NUNCA vira entrega de imagem.
const urlsHistorico = new Set();
for (const h of (pacote.historico || [])) {
  const urls = String(h.conteudo || '').match(/https?:\/\/\S+/g) || [];
  urls.forEach(u => urlsHistorico.add(u));
}
function ehFotoDoCliente(url) {
  const u = String(url || '').trim();
  if (!u) return true;
  if (u.includes('lookaside.fbsbx.com') || u.includes('ig_messaging_cdn')) return true;
  if (urlsHistorico.has(u)) return true;
  return false;
}
const fotosPermitidas = (briefing.fotos || []).filter(f => !ehFotoDoCliente(f && f.url));
// ---- PRIMEIRA INTERAÇÃO — detecção partilhada pelos dois blocos abaixo ----
const jaFalamosAntes = (pacote.historico || []).some(h =>
  ((h.direccao || h.direcao) === 'enviada')
);
// O histórico central é a autoridade para saber se a Carol já falou. Em turnos
// posteriores, remove reapresentações e respostas quase idênticas antes de
// criar ações de saída. A trava é determinística e independe do modelo.
if (jaFalamosAntes) {
  const identidadeCarol = /\b(?:sou|soy|i\s*(?:'m|am))\b[^.!?]{0,100}\bcarol\b|\bcarol\b[^.!?]{0,80}\bmiranda skin experts\b/i;
  const anteriores = (pacote.historico || []).filter((item) => (item.direccao || item.direcao) === 'enviada')
    .slice(-8).map((item) => String(item.conteudo || '')).filter(Boolean);
  const frasesAnteriores = anteriores.flatMap((mensagem) => String(mensagem).split(/(?<=[.!?])\s+|\n+/))
    .map((frase) => frase.trim()).filter(Boolean);
  const saudacaoReiniciada = /^(?:[¡¿]?\s*)?(?:ol[áa]+|oi+|hola+|hello|hi|hey+|bom dia|boa tarde|boa noite|good (?:morning|afternoon|evening)|buen(?:os d[ií]as|as tardes|as noches)|tudo bem|todo bien|how are you)(?:[,.!¿?¡\s]+(?:tudo bem|todo bien|how are you))?[,.!¿?¡\s]*$/i;
  mensagens = mensagens.map((mensagem) => String(mensagem).split(/(?<=[.!?])\s+|\n+/)
    .map((frase) => frase.trim()).filter((frase, index) => frase && !identidadeCarol.test(frase) &&
      !(index === 0 && saudacaoReiniciada.test(frase)) && !frasesAnteriores.some((anterior) => saoParecidas(anterior, frase)))
    .join(' ').trim()).filter(Boolean);
  mensagens = mensagens.filter((mensagem) => !anteriores.some((anterior) => saoParecidas(anterior, mensagem)));
}
let perguntaMantida = false;
mensagens = mensagens.map((mensagem) => String(mensagem).split(/(?<=[.!?])\s+|\n+/).map((frase) => frase.trim()).filter((frase) => {
  if (!frase.includes('?')) return true;
  if (perguntaMantida) return false;
  perguntaMantida = true;
  return true;
}).join(' ').trim()).filter(Boolean);
// ---- SAUDAÇÃO DE 2 BALÕES NO WHATSAPP (pedido do Arthur, 05/10) ----
// Só no WHATSAPP e só na PRIMEIRA interação da vida do cliente: a resposta
// sai SEMPRE em exatamente 2 balões:
//   1) saudação curta da Carol com o primeiro nome do lead;
//   2) o conteúdo do Redator (responde ao contexto, se houver) SEM saudação
//      nem auto-apresentação duplicada; se não sobrar nada, pergunta de
//      descoberta sobre a pele.
// A pergunta de idioma NÃO existe no WhatsApp (removida a pedido do Arthur,
// 05/10) — segue existindo apenas no Instagram, no bloco seguinte.
if (!jaFalamosAntes && canalConversaTrava === 'whatsapp' && !tudoBloqueado && !redatorFalhou && mensagens.length > 0) {
  // primeiro nome do lead — só entra se parecer nome de verdade
  const nomeBrutoSaud = String(((entradaCerebroTrava.contacto || {}).nome) || '').trim();
  const primeiroTokenSaud = nomeBrutoSaud.split(/\s+/)[0] || '';
  let primeiroNomeSaud = primeiroTokenSaud.replace(/[^\p{L}\-']/gu, '');
  if (primeiroNomeSaud.length < 2 || /\d/.test(primeiroTokenSaud)) primeiroNomeSaud = '';
  const nomeSaud = primeiroNomeSaud
    ? ' ' + primeiroNomeSaud.charAt(0).toUpperCase() + primeiroNomeSaud.slice(1)
    : '';

  let saudacaoWpp;
  if (idiomaConversa.startsWith('en')) {
    saudacaoWpp = 'Hi' + nomeSaud + ', how are you? I\'m Carol from Miranda Skin Experts and I\'ll be taking care of you today.';
  } else if (idiomaConversa.startsWith('es')) {
    saudacaoWpp = 'Hola' + nomeSaud + ', ¿todo bien? Soy Carol, de Miranda Skin Experts, y voy a atenderte hoy.';
  } else {
    saudacaoWpp = 'Olá' + nomeSaud + ', tudo bem? Sou a Carol da Miranda Skin Experts e vou realizar seu atendimento.';
  }

  // 2º balão: junta o que o Redator escreveu e remove saudação/apresentação
  // duplicada do início (o balão 1 já cumpre esse papel)
  let corpoWpp = mensagens.join(' ')
    .replace(/\b(?:sou|soy)\s+(?:a\s+)?carol[^.!?]*[.!?]\s*/gi, '')
    .replace(/\bi\s*'?\s*a?m\s+carol[^.!?]*[.!?]\s*/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
  // remove saudações/quebra-gelos residuais do INÍCIO, em cadeia
  // ("Olá! Tudo bem? Que bom te ver!" → remove os três)
  const lixoInicialWpp = /^\s*[¡¿]?\s*(?:ol[áa]+|oi+|hello|hi|hey+|hola+|bom dia|boa tarde|boa noite|good\s+(?:morning|afternoon|evening)|buen[oa]s(?:\s+d[ií]as|\s+tardes|\s+noches)?|tudo\s+bem|tudo\s+bom|como\s+vai|how\s+are\s+you|todo\s+bien|c[óo]mo\s+est[áa]s?|que\s+bom\s+te[r]?\s+(?:ver|voc[êe])[^.!?\n]{0,40})[^.!?\n]{0,60}[.!?,]\s*/i;
  for (let liWpp = 0; liWpp < 4 && lixoInicialWpp.test(corpoWpp); liWpp++) {
    corpoWpp = corpoWpp.replace(lixoInicialWpp, '');
  }
  corpoWpp = corpoWpp.trim();

  if (!corpoWpp) {
    if (idiomaConversa.startsWith('en')) {
      corpoWpp = 'Is there anything you\'d like to improve about your skin, or a treatment you\'re curious about?';
    } else if (idiomaConversa.startsWith('es')) {
      corpoWpp = '¿Hay algo que te gustaría mejorar en tu piel, o algún tratamiento que te interese?';
    } else {
      corpoWpp = 'Tem algo que você gostaria de melhorar na sua pele, ou algum tratamento que te interessa?';
    }
  } else {
    corpoWpp = corpoWpp.charAt(0).toUpperCase() + corpoWpp.slice(1);
  }

  mensagens = [saudacaoWpp, corpoWpp];
}
// ---- BALÃO DE IDIOMA NA PRIMEIRA INTERAÇÃO (pedido do Arthur, 01/09) ----
// (05/10) AGORA SÓ NO INSTAGRAM/META — no WhatsApp a pergunta de idioma foi
// removida por completo (bloco acima cuida da saudação do WhatsApp).
// Só na PRIMEIRA interação da vida do cliente (nenhuma mensagem 'enviada' no
// histórico = a Carol nunca respondeu antes): anexa um balão final perguntando
// em que idioma o cliente prefere continuar. A partir da segunda resposta o
// histórico já tem mensagens enviadas, então é impossível repetir. A resposta
// do cliente ("Español", "English"...) é capturada pelo Agente de Contexto e
// fica salva em dados.idioma — não precisa de mais nada. Se ele ignorar a
// pergunta, o idioma continua sendo detectado normalmente das mensagens.
// Idioma do balão: o detectado na conversa; não detectado/incerto → inglês.
if (!jaFalamosAntes && canalConversaTrava !== 'whatsapp' && !tudoBloqueado && !redatorFalhou && mensagens.length > 0) {
  let perguntaIdioma;
  if (idiomaConversa.startsWith('pt')) {
    perguntaIdioma = 'Ah, e para eu te atender melhor: você prefere continuar em Português, English ou Español?';
  } else if (idiomaConversa.startsWith('es')) {
    perguntaIdioma = 'Ah, y para atenderte mejor: ¿prefieres seguir en Español, English o Português?';
  } else {
    perguntaIdioma = 'Oh, and so I can help you better: would you prefer to continue in English, Español or Português?';
  }
  if (!mensagens.some(m => saoParecidas(m, perguntaIdioma))) {
    mensagens.push(perguntaIdioma);
  }
}
// ---- fim das travas ----
const bloqueioTotal = (tudoBloqueado || redatorFalhou) && !mensagemTemplate;
// template só perde os emojis AQUI, na entrega — a validação de template
// autêntico e o dedupe acima continuam a ver a versão original com emojis
const mensagemTemplateEntrega = mensagemTemplate ? semEmojis(mensagemTemplate) : '';
const entregas = [
  ...mensagens.map(texto => ({ tipo: 'texto', texto })),
  ...(mensagemTemplateEntrega ? [{ tipo: 'texto', texto: mensagemTemplateEntrega }] : []),
  ...(bloqueioTotal ? [] : fotosPermitidas.map(f => ({
    tipo: 'imagem',
    url: f.url,
    legenda: semEmojis(f.legenda || '')
  })))
];
return [
  {
    json: {
      output: JSON.stringify({
        acao: entregas.length ? 'entregar' : 'sem_resposta',
        modulo: briefing.modulo || 'geral',
        entregas,
        handoff,
        operacoes: briefing.operacoes || {},
        contexto_actualizado: briefing.contexto_actualizado || {},
        erro
      })
    }
  }
];

